        Set<String> subSet = new HashSet<>();
        int len = s.length();
        for (int i=0; i<len; i++){
            for (int j=i+1; j<=len; j++){
                String sub = s.substring(i,j);
                subSet.add(sub);
                subSet.add(new StringBuilder(sub).reverse().toString());
            }
        }
        if (idx==0){
